from review import card,save,DATE
i='TCS-4039';_,c=card(i);refs=c['references'];refs[0]['locator']='Introduction, page 24:3, streaming comparison; Section 2 communication model and Definitions 3–5.'
refs += [dict(id='full',title='The Bottleneck Complexity of Secure Multiparty Computation — full author manuscript',authors='Elette Boyle; Abhishek Jain; Manoj Prabhakaran; Ching-Hua Yu',year=2018,url='https://www.cse.iitb.ac.in/~mp/pub/bottleneck.pdf',pdf_url='https://www.cse.iitb.ac.in/~mp/pub/bottleneck.pdf',locator='Introduction page 3 and Section 2.1. The full manuscript retains the same qualitative streaming-separation question; its cover does not give a later revision date.'),dict(id='later',title='Lower Bounds on the Bottleneck Complexity of Secure Multiparty Computation',authors='Reo Eriguchi; Keitaro Hiwatashi',year=2025,url='https://eprint.iacr.org/2025/990',pdf_url='https://eprint.iacr.org/2025/990.pdf',locator='Introduction and Section 1.1: perfectly correct, perfectly private MPC with correlated randomness. Sections 3–5 and Corollary 2 concern security-dependent lower bounds, including restricted communication patterns.')]
issue='The source gives no quantitative bottleneck-versus-space separation, no fixed streaming pass budget or quantifier over pass counts, and no input-order convention (prescribed order, adversarial order or a freely chosen order). It also leaves the input-block growth, required constructibility of the function family and matching correctness/randomness conventions for this comparison unstated. These choices must be recovered before this becomes one benchmark proposition.'
notes=['Recovered the source’s comparison without any secrecy requirement, rather than an MPC security problem.','Defined bottleneck as maximum over parties and inputs of expected sent-plus-received bits, not expected maximum load or total communication.','Recovered synchronous point-to-point communication and prefix-free messages excluding zero-cost signaling by silence.','Explained the source’s small-memory, few-pass simulation, but retained the missing pass/order and quantitative separation specifications.','Read the full author manuscript and checked later security-dependent lower bounds, which do not supply the missing nonsecure streaming target.']
save(i,dict(title='Bottleneck communication versus streaming space',formal='Separate low-bottleneck distributed computation from low-memory streaming computation of the same function family, without imposing secrecy on the distributed protocol. The source asks for functions with low per-party communication that cannot be computed with low streaming memory. It does not specify the asymptotic separation, the allowed number of streaming passes or the input-order quantifier, so this is a research question requiring specification rather than a completed mathematical proposition.',definitions='''For n parties P₁,…,Pₙ, party Pᵢ initially holds only its own input block xᵢ, a string of k bits in the source’s illustrative setting. A function maps the ordered n-tuple of blocks to an output, with a single output bit at one party allowed in the source’s general discussion. This is the number-in-hand model; parties do not initially know one another’s blocks. The selected question does not require privacy, resistance to malicious behavior or cryptographic hardness assumptions.

Communication is synchronous and point to point. In round t, a party chooses its outgoing messages from its own input, random tape and previously received messages. Each message on an edge in a round uses a prefix-free code agreed by its endpoints. In particular, one cannot encode an arbitrary value for free through silence or a chosen waiting time. Let Cᵢ(π,x,r) be the total number of bits sent plus received by party i in protocol π on input tuple x and random tapes r. The source’s cost is BC(π)=max_i sup_x E_r[Cᵢ(π,x,r)]. The maximum is outside the expectation: this is not E_r[max_i Cᵢ], and it is not the sum of all parties’ loads. Its function-level cost minimizes this quantity over protocols that meet the required correctness convention. The source allows randomized protocols but does not fix a common error criterion in the streaming-separation passage. Its separate compiler assumes efficient next-message computation and a fixed communication pattern; those extra assumptions must not automatically be imposed on every protocol in this nonsecure comparison.

A streaming computation processes input blocks sequentially while retaining a bounded state between blocks. A pass is a complete traversal of the chosen stream; a multipass algorithm may traverse it again. The source observes that a p-pass algorithm whose communicated state has at most s bits gives a protocol of O(ps) per-party communication by passing that state around the corresponding chain or cycle. This statement uses the same input order and correctness convention in the two computations. It explains why both memory and pass count enter the comparison; a claim about memory alone does not fix the simulated communication cost.

To make the requested separation precise one must specify a family fₙ and the relation of k to n; an upper bound B(n,k) on distributed bottleneck; the allowed streaming order or quantifier over orders; a pass bound p(n,k); and a lower bound S(n,k) on streaming space with a stated asymptotic gap. One must also fix deterministic versus randomized correctness, how memory is bounded over random tapes, and any uniformity or explicit-construction requirement. The saved source does not make these choices. No particular polynomial gap, one-pass restriction, symmetric-function requirement or adversarial-order convention is certified by this card.''',question_type='yes_no',answer_criterion='Pending a source-supported specification of the comparison. A complete result must exhibit the required function family and prove the distributed upper bound and streaming lower bound for precisely the same input and output task, with the stated order, pass, error and resource conventions. Until those parameters are fixed, a separation for one chosen interpretation is not a verified resolution of the saved question.',context_blocks=[dict(title='Per-party load is the comparison',text='The source separates the load on the busiest participant from total communication. It observes that computations can distribute their work over communication graphs with more structure than the chain or repeated cycle representing a streaming computation.',citation='primary'),dict(title='Streaming supplies one sufficient condition',text='Small memory and few passes give low bottleneck through transfer of the streaming state. The requested converse separation therefore depends on which stream orders and pass counts are allowed; the introduction states no precise quantitative version.',citation='full'),dict(title='General bottleneck lower bounds answer another question',text='The source also gives an existential near-linear bottleneck lower bound for general functions. That shows that small bottleneck is not universal, whereas this card asks for a function that does have small bottleneck yet is hard for streaming.',citation='primary'),dict(title='Later lower bounds impose security',text='Eriguchi and Hiwatashi’s 2025 report studies perfectly private MPC, including correlated randomness and restrictions on communication patterns. Those hypotheses differ from the nonsecure computation comparison here and do not fix its missing streaming parameters.',citation='later')],why='Asks whether distributing intermediate state across a communication network permits computations beyond those captured by a small sequential streaming state. A precise separation would clarify what per-party communication measures beyond the memory-times-passes simulation.',progress=[dict(date='2018',text='The source introduces the nonsecure bottleneck measure and poses a qualitative separation from low-memory streaming; the full manuscript repeats it.',citation='primary'),dict(date='2025',text='Later lower bounds address perfectly private MPC and correlated randomness rather than this unspecified nonsecure streaming comparison.',citation='later')],references=refs,status='uncertain',status_note='The nonsecure communication definition and qualitative question were checked in the conference and full author versions. Later searches through 12 September 2026 and the 2025 security-dependent lower-bound report did not recover a precise pass/order/separation target. Current openness cannot be certified for an unspecified comparison.',model_self_contained=False,requires_context=True,review_note=issue,statement_review=dict(reviewed_on=DATE,status='needs_specification',notes=notes,remaining_issue=issue,scope='Individual source-based review; no substituted target or proof verification.'),importance=dict(score=c['importance']['score'],method='editorial',reason='A structural comparison between balanced distributed communication and sequential memory, whose value depends on recovering a substantive precise separation. Existing score retained.',assessed_on=DATE),working_summary=dict(sentences=['Bottleneck complexity charges the largest expected communication load of any participant.','A small-memory streaming algorithm with few passes gives a low-bottleneck distributed protocol.','The source asks for a function with small bottleneck but large streaming memory, without secrecy requirements.','Its passage does not fix the pass budget, input-order convention or quantitative gap.','The card records those missing choices and distinguishes subsequent private-MPC lower bounds.'],basis='saved_sources',source_basis='source-text',written_on=DATE,source_refs=['primary','full','later'])),notes=notes,checked_sources=[r['url'] for r in refs],state='improved_unfinished')
